<?phpif (!current_user_can('manage_options')) {    return;}$message = '';$setting_website = get_option('_tnm_settings_set_contact_us', []);if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['submit'])) {    if (        !isset($_POST['_nonce_tns_setting_general']) ||        !wp_verify_nonce(            $_POST['_nonce_tns_setting_general'],            '_nonce_tns_setting_general'        )    ) {        $message = '            <div class="alert alert-danger alert-dismissible fade show mb-4" role="alert">                Security validation failed!                <button type="button" class="btn-close" data-bs-dismiss="alert"></button>            </div>        ';    } else {        $time_work_parts = explode(            '|',            sanitize_text_field($_POST['working-time'] ?? '')        );        $setting_data = [            'email_contact'       => sanitize_text_field($_POST['email-contact-us'] ?? ''),            'phone_number_store'  => sanitize_text_field($_POST['phone-number-store'] ?? ''),            'phone_number_mobile' => sanitize_text_field($_POST['phone-number-1'] ?? ''),            'start_work_h'        => $time_work_parts[0] ?? '',            'end_work_h'          => $time_work_parts[1] ?? '',            'start_work'          => $time_work_parts[2] ?? '',            'end_work'            => $time_work_parts[3] ?? '',            'working_time_raw'    => sanitize_text_field($_POST['working-time'] ?? ''),            'address'             => sanitize_text_field($_POST['address-c-us'] ?? ''),            'iframe_map_url'      => sanitize_text_field($_POST['address-fs'] ?? ''),        ];        update_option('_tnm_settings_set_contact_us', $setting_data);        $setting_website = $setting_data;        $message = '            <div class="alert alert-success alert-dismissible fade show mb-4" role="alert">                Settings saved successfully!                <button type="button" class="btn-close" data-bs-dismiss="alert"></button>            </div>        ';    }}?><style>    .tns-settings-wrapper {        width: 100%;        max-width: none;        margin: 0;        padding: 20px 20px 20px 0;        box-sizing: border-box;    }    .tns-settings-wrapper *,    .tns-settings-wrapper *::before,    .tns-settings-wrapper *::after {        box-sizing: border-box;    }    .tns-settings-wrapper .card {        width: 100%;        max-width: none;    }    .tns-settings-wrapper .card-body {        width: 100%;    }    .tns-settings-wrapper .row {        width: 100%;    }    .tns-settings-wrapper .form-control {        width: 100%;    }    /*     * WordPress Admin content area     */    #wpbody-content {        padding-bottom: 40px;    }    /*     * Remove unnecessary WordPress default width     */    .tns-settings-wrapper {        display: block;    }    @media (max-width: 782px) {        .tns-settings-wrapper {            padding: 15px 10px;        }    }</style><div class="tns-settings-wrapper">    <!-- Page Header -->    <div class="d-flex justify-content-between align-items-center mb-4">        <div>            <h4 class="mb-1">                Settings                <span class="text-primary">                    <?php echo esc_html(get_admin_page_title()); ?>                </span>            </h4>            <p class="text-muted mb-0">                Manage your contact information and working hours.            </p>        </div>    </div>    <!-- Message -->    <?php if (!empty($message)) : ?>        <?php echo $message; ?>    <?php endif; ?>    <!-- Settings Card -->    <div class="card border-0 shadow-sm">        <!-- Card Header -->        <div class="card-header bg-white border-bottom py-3">            <div class="d-flex align-items-center">                <i class="fas fa-address-book text-primary me-2"></i>                <h5 class="mb-0">                    Contact & Business Information                </h5>            </div>        </div>        <!-- Card Body -->        <div class="card-body p-4">            <form method="post">                <div class="row g-4">                    <!-- Email -->                    <div class="col-12 col-md-6 col-xl-3">                        <label                                for="email-contact-us"                                class="form-label fw-semibold"                        >                            Email Address                        </label>                        <input                                class="form-control"                                type="email"                                id="email-contact-us"                                name="email-contact-us"                                placeholder="Email address"                                value="<?php echo esc_attr(                                    $setting_website['email_contact'] ?? ''                                ); ?>"                        >                        <div class="form-text">                            Example: contact@example.com                        </div>                    </div>                    <!-- Store Phone -->                    <div class="col-12 col-md-6 col-xl-3">                        <label                                for="phone-number-store"                                class="form-label fw-semibold"                        >                            Store Phone Number                        </label>                        <input                                class="form-control"                                type="text"                                id="phone-number-store"                                name="phone-number-store"                                placeholder="Store phone number"                                value="<?php echo esc_attr(                                    $setting_website['phone_number_store'] ?? ''                                ); ?>"                        >                        <div class="form-text">                            Enter the store landline number.                        </div>                    </div>                    <!-- Mobile -->                    <div class="col-12 col-md-6 col-xl-3">                        <label                                for="phone-number-1"                                class="form-label fw-semibold"                        >                            Mobile Number                        </label>                        <input                                class="form-control"                                type="text"                                id="phone-number-1"                                name="phone-number-1"                                placeholder="Mobile number"                                value="<?php echo esc_attr(                                    $setting_website['phone_number_mobile'] ?? ''                                ); ?>"                        >                        <div class="form-text">                            Example: 09123456789                        </div>                    </div>                    <!-- Working Hours -->                    <div class="col-12 col-md-6 col-xl-3">                        <label                                for="working-time"                                class="form-label fw-semibold"                        >                            Working Hours                        </label>                        <input                                class="form-control"                                type="text"                                id="working-time"                                name="working-time"                                placeholder="8|15|7|18"                                value="<?php echo esc_attr(                                    $setting_website['working_time_raw'] ?? ''                                ); ?>"                        >                        <div class="form-text">                            Format: 8|15|7|18                        </div>                    </div>                    <!-- Physical Address -->                    <div class="col-12">                        <label                                for="address-c-us"                                class="form-label fw-semibold"                        >                            Physical Address                        </label>                        <input                                class="form-control"                                type="text"                                id="address-c-us"                                name="address-c-us"                                placeholder="Enter your physical address"                                value="<?php echo esc_attr(                                    $setting_website['address'] ?? ''                                ); ?>"                        >                        <div class="form-text">                            Enter the physical address of your business.                        </div>                    </div>                    <!-- Google Maps -->                    <div class="col-12">                        <label                                for="address-fs"                                class="form-label fw-semibold"                        >                            Google Maps URL                        </label>                        <input                                class="form-control"                                type="text"                                id="address-fs"                                name="address-fs"                                placeholder="Enter Google Maps iframe src URL"                                value="<?php echo esc_attr(                                    $setting_website['iframe_map_url'] ?? ''                                ); ?>"                        >                        <div class="form-text">                            Enter the <code>src</code> URL from your Google Maps iframe.                        </div>                    </div>                </div>                <!-- Submit -->                <div class="mt-4 pt-3 border-top">                    <?php                    wp_nonce_field(                        '_nonce_tns_setting_general',                        '_nonce_tns_setting_general'                    );                    ?>                    <button                            type="submit"                            name="submit"                            class="btn btn-primary px-4"                    >                        <i class="fas fa-save me-2"></i>                        Save Settings                    </button>                </div>            </form>        </div>    </div></div>